import{_ as o,o as n,c as t,a3 as i}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Offline Slowdown and Possible Remedies (Fixed)","description":"","frontmatter":{"translationSource":{"title":"下线降速现象与相关补救方法探究（已被修复）","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=XnpxncxXlSmIhlbhisNQ8d","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/offline-slowdown-and-possible-remedies"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/offline-slowdown-and-possible-remedies"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/offline-slowdown-and-possible-remedies"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/offline-slowdown-and-possible-remedies"}]]},"headers":[],"relativePath":"offline-slowdown-and-possible-remedies.md","filePath":"logistics/src/page-XnpxncxXlSmIhlbhisNQ8d.md"}'),l={name:"offline-slowdown-and-possible-remedies.md"};function s(a,e,d,r,f,p){return n(),t("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><span class="logistics-source-anchor" id="下线降速现象与相关补救方法探究-已被修复" aria-hidden="true"></span><h1 id="offline-slowdown-and-possible-remedies-fixed" tabindex="-1">Offline Slowdown and Possible Remedies (Fixed) <a class="header-anchor" href="#offline-slowdown-and-possible-remedies-fixed" aria-label="Permalink to &quot;Offline Slowdown and Possible Remedies (Fixed)&quot;">​</a></h1><blockquote><p>Source page ID: <code>XnpxncxXlSmIhlbhisNQ8d</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=XnpxncxXlSmIhlbhisNQ8d" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Known observations: belt speed fluctuates offline approximately every 5 minutes, for a total fluctuation duration below 4s. Belts and filtering/counting control ports may fluctuate simultaneously offline. Reports disagree on the resulting slowdown and may differ by player.</p><p>Reducing belts to half rate sometimes alleviates offline slowdown, apparently without eliminating it; there is no unified conclusion.</p><p>Currently, any logistics route containing a belt is thought to slow to that belt&#39;s speed when its speed fluctuates.</p><p>Nonmember 乾震 proposed compensating power with a differential structure: belt–control port&gt;0.5–belt. Belts and control ports can therefore provide the required rate difference.</p><p>Later tests found that merging two half-duty-cycle belts can slow down or block items. Consider this when reducing or eliminating offline slowdown.</p><p>Some tests support equal offline slowdown for belts and control ports.</p><p>Some experiments suggest non-full-rate belts may be unaffected by offline slowdown.</p></div>',1)])])}const u=o(l,[["render",s]]);export{h as __pageData,u as default};
